package io.baozhu.atlas.api; import io.baozhu.atlas.service.QualityService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/quality") public class QualityController {private final QualityService service;public QualityController(QualityService s){service=s;} @PostMapping("/evaluate") public QualityEvaluateResponse evaluate(@Valid @RequestBody QualityEvaluateRequest r){return service.evaluate(r);}}
